def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r == h - r - 1:
            split = ("h", r)
            break
    if split is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
                split = ("v", c)
                break
    if split is None:
        raise ValueError("no centered divider found")
    orientation, idx = split
    if orientation == "h":
        first, second = grid[:idx], grid[idx + 1:]
    else:
        first = [row[:idx] for row in grid]
        second = [row[idx + 1:] for row in grid]
    common = set(cell for row in first for cell in row) & set(cell for row in second for cell in row)
    if len(common) != 1:
        raise ValueError(f"expected one shared color, got {common}")
    background = next(iter(common))
    return [[3 if first[r][c] == background and second[r][c] == background else background
             for c in range(len(first[0]))] for r in range(len(first))]

